    async function handleChangePassword() {
        if (cpSubmitting) return;
        if (cpNew !== cpConfirm) {
            toast({
                title: "Passwords don't match",
                description: "Please re-enter the same password in both fields.",
                variant: "destructive"
            });
            return;
        }
        if (cpNew.length < 6) {
            toast({
                title: "Password too short",
                description: "New password must be at least 6 characters.",
                variant: "destructive"
            });
            return;
        }
        setCpSubmitting(true);
        try {
            const res = await fetch("/api/auth/change-password", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify({
                    currentPassword: cpCurrent,
                    newPassword: cpNew
                })
            });
            const data = await res.json();
            if (!res.ok || !data.ok) {
                toast({
                    title: "Change password failed",
                    description: data?.error || "Could not change the password.",
                    variant: "destructive"
                });
            } else {
                toast({
                    title: "Password changed",
                    description: "Your password has been updated. Use the new one next time you sign in."
                });
                setChangePasswordOpen(false);
                setCpCurrent("");
                setCpNew("");
                setCpConfirm("");
            }
        } catch (e) {
            toast({
                title: "Change password failed",
                description: "Network error.",
                variant: "destructive"
            });
        } finally{
            setCpSubmitting(false);
        }
    }
